def count_vowels(s: str) -> int:
    vowels = 'aeiouy'
    count = 0
    for char in s.lower():
        if char in vowels:
            count += 1
    return count

def is_prime(n: int) -> bool:
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def fib(n: int) -> int:
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fib(n-1) + fib(n-2)

def is_palindrome(s: str) -> bool:
    s = s.lower().replace(" ", "")
    return s == s[::-1]

def gcd(a: int, b: int) -> int:
    while b != 0:
        a, b = b, a % b
    return a

def brackets_balanced(s: str) -> bool:
    stack = []
    brackets = {'(': ')', '[': ']', '{': '}'}
    for char in s:
        if char in brackets:
            stack.append(char)
        elif not stack or brackets[stack.pop()] != char:
            return False
    return not stack

print(brackets_balanced("()[]{}"))  # True
print(brackets_balanced("(]"))  # False
print(brackets_balanced("([{}])"))  # True
print(brackets_balanced("([)]"))  # False

def missing_number(nums: list) -> int:
    n = len(nums)
    return n * (n + 1) // 2 - sum(nums)

def two_sum(nums: list, target: int) -> bool:
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] + nums[j] == target:
                return True
    return False

nums = [2, 7, 11, 15]
target = 9
print(two_sum(nums, target))

def rotate(nums: list, k: int) -> list:
    k = k % len(nums)
    return nums[-k:] + nums[:-k]

def count_inversions(nums: list) -> int:
    count = 0
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] > nums[j]:
                count += 1
    return count

def digit_root(n: int) -> int:
    while n > 9:
        n = sum(int(digit) for digit in str(n))
    return n
